#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main original_unmodified_cli_main
#include "../rodrigues-cuda/main.cu"
#undef main
static std::vector<float> readf(const char*name,size_t count){std::vector<float>v(count);FILE*f=fopen(name,"rb");if(!f||fread(v.data(),4,count,f)!=count)exit(2);fclose(f);return v;}
int main(){const int N=4099,G=12;const float guard=12345.25f;auto pts=readf("points_f32.bin",3*N);std::vector<double>oracle(24*3*N);FILE*f=fopen("oracle_f64.bin","rb");if(!f||fread(oracle.data(),8,oracle.size(),f)!=oracle.size())return 3;fclose(f);float wx=-.3f,wy=-.6f,wz=.15f,norm=1.f/sqrtf(wx*wx+wy*wy+wz*wz);float3 axes[]={make_float3(wx*norm,wy*norm,wz*norm),make_float3(0,0,1)};float angles[]={0,.5f,float(3.14159265358979323846/2)};bool all=true;
 for(int trial=0;trial<=5;trial++){bool ok=true;double maxerr=0;size_t offset=0;std::vector<float>prefix,outputs;std::vector<double>times;
 for(int width:{3,4})for(float3 axis:axes)for(float angle:angles)for(int R:{1,17}){int W=N*width+2*G;std::vector<float>initial(W,guard),before(W),out(W);for(int i=0;i<N;i++){for(int k=0;k<3;k++)initial[G+i*width+k]=pts[3*i+k];if(width==4)initial[G+i*width+3]=float(((i+1)%17)-8)/8;}std::vector<float>params={guard,float(N),float(R),float(width),angle,axis.x,axis.y,axis.z,guard},par(9),afterpar(9);float*d,*dp;cudaMalloc(&d,W*4);cudaMalloc(&dp,36);cudaMemcpy(d,initial.data(),W*4,cudaMemcpyHostToDevice);cudaMemcpy(dp,params.data(),36,cudaMemcpyHostToDevice);auto launch=[&](){if(width==3)rotate<<<(N+255)/256,256>>>(N,angle,axis,(float3*)(d+G));else rotate2<<<(N+255)/256,256>>>(N,angle,axis,(float4*)(d+G));};
 if(trial==0){launch();ok &=cudaDeviceSynchronize()==cudaSuccess;cudaFree(d);cudaFree(dp);offset+=3*N;continue;}
 cudaMemcpy(before.data(),d,W*4,cudaMemcpyDeviceToHost);cudaMemcpy(par.data(),dp,36,cudaMemcpyDeviceToHost);ok &=memcmp(before.data(),initial.data(),W*4)==0&&memcmp(par.data(),params.data(),36)==0;cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int r=0;r<R;r++)launch();ok &=cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/R);cudaMemcpy(out.data(),d,W*4,cudaMemcpyDeviceToHost);cudaMemcpy(afterpar.data(),dp,36,cudaMemcpyDeviceToHost);ok &=memcmp(afterpar.data(),params.data(),36)==0;for(int j=0;j<G;j++)ok &=out[j]==guard&&out[W-G+j]==guard;double budget=5e-6+8e-7*R;double an=sqrt(double(axis.x)*axis.x+double(axis.y)*axis.y+double(axis.z)*axis.z),u[]={axis.x/an,axis.y/an,axis.z/an};
 for(int i=0;i<N;i++){double a2=0,p2=0,adot=0,pdot=0;for(int k=0;k<3;k++){double a=out[G+i*width+k],p=pts[3*i+k],err=fabs(a-oracle[offset+3*i+k]);maxerr=std::max(maxerr,err);ok &=isfinite(a)&&err<=budget;a2+=a*a;p2+=p*p;adot+=a*u[k];pdot+=p*u[k];}ok &=fabs(sqrt(a2)-sqrt(p2))<=3*budget&&fabs(adot-pdot)<=3*budget;if(width==4)ok &=out[G+i*width+3]==0&&!signbit(out[G+i*width+3]);}
 prefix.insert(prefix.end(),before.begin(),before.end());prefix.insert(prefix.end(),par.begin(),par.end());outputs.insert(outputs.end(),out.begin(),out.end());offset+=3*N;cudaFree(d);cudaFree(dp);
 }if(!trial){if(!ok)return 4;continue;}all &=ok;std::vector<float>artifact=prefix;artifact.insert(artifact.end(),outputs.begin(),outputs.end());char path[80];snprintf(path,80,"output_trial%d.bin",trial);f=fopen(path,"wb");if(!f)return 5;fwrite(artifact.data(),4,artifact.size(),f);fclose(f);double total=0;for(double t:times)total+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"sum24_separate_inplace_kernel_hostwindows_divided_by_R\",\"jit_excluded\":true,\"path_times_seconds\":[",trial,total,ok?"true":"false",artifact.size(),maxerr);for(size_t j=0;j<times.size();j++)printf("%s%.12g",j?",":"",times[j]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path,artifact.size());
 }puts(all?"PASS":"FAIL");return all?0:1;}
